#include <bits/stdc++.h>
using namespace std;
using ll=long long;
struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void join(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}};
struct BIT{int n;vector<int>t;BIT(int n=0):n(n),t(n+1){}void add(int x,int v){for(++x;x<=n;x+=x&-x)t[x]+=v;}int sum(int x){int r=0;for(;x>0;x-=x&-x)r+=t[x];return r;}int kth(int k){int p=0;for(int step=1<<20;step;step>>=1)if(p+step<=n&&t[p+step]<k){p+=step;k-=t[p];}return p;}};
ll power(ll a,ll b,ll mod=1000000007){ll r=1;for(;b;b>>=1,a=a*a%mod)if(b&1)r=r*a%mod;return r;}
int main(){int n;ll L;cin>>n>>L;vector<array<ll,4>>ramps(n);vector<ll>positions={0,L};for(auto&a:ramps){cin>>a[0]>>a[1]>>a[2]>>a[3];if(a[0]>=a[3]){positions.push_back(a[0]-a[3]);positions.push_back(a[0]+a[1]);}}sort(positions.begin(),positions.end());positions.erase(unique(positions.begin(),positions.end()),positions.end());auto id=[&](ll x){return lower_bound(positions.begin(),positions.end(),x)-positions.begin();};struct E{int v,ramp;ll weight;};int size=positions.size();vector<vector<E>>g(size);for(int i=1;i<size;i++){ll w=positions[i]-positions[i-1];g[i].push_back({i-1,-1,w});g[i-1].push_back({i,-1,w});}for(int i=0;i<n;i++){auto&a=ramps[i];if(a[0]>=a[3])g[id(a[0]-a[3])].push_back({(int)id(a[0]+a[1]),i,a[3]+a[2]});}vector<ll>d(size,LLONG_MAX/4);vector<int>from(size,-1),used(size,-1);priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>>q;d[0]=0;q.push({0,0});while(!q.empty()){auto[du,u]=q.top();q.pop();if(du!=d[u])continue;for(auto&e:g[u])if(du+e.weight<d[e.v]){d[e.v]=du+e.weight;from[e.v]=u;used[e.v]=e.ramp;q.push({d[e.v],e.v});}}vector<int>chosen;for(int u=size-1;u;u=from[u])if(used[u]>=0)chosen.push_back(used[u]+1);reverse(chosen.begin(),chosen.end());cout<<d.back()<<'\n'<<chosen.size()<<'\n';for(int v:chosen)cout<<v<<' ';cout<<'\n';}
